def binary_search(arr: list[int], target: int, low: int = 0, high: int | None = None) -> int:
    """
    Perform a recursive binary search on a sorted list of integers.

    Args:
        arr: A sorted list of integers.
        target: The integer value to search for.
        low: The lower index bound (inclusive).
        high: The upper index bound (inclusive). Defaults to len(arr) - 1.

    Returns:
        The index of the target if found, otherwise -1.
    """
    if high is None:
        high = len(arr) - 1

    if low > high:
        return -1

    mid: int = (low + high) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search(arr, target, mid + 1, high)
    else:
        return binary_search(arr, target, low, mid - 1)
